const e="ibfac-bible-fine-arts",l=2020,t="Built from the organiser's 2020 Bible category rules (an old edition: dates are Variables). The document prints no competition date, venue, fees, registration form steps, prizes other than the Star Quizzer award, judging criteria or ages. The one contact printed is a named person and a mailing address for Radio Program entries, kept as a Variable.",o={Title:"Rules & Criteria",Subtitle:"IBFAC Bible category. Read these rules before you register. These are the 2020 rules, so check the current year's date and quiz portion.",NoticeTitle:"Please Read Before Registering",Notice:"These rules are from the 2020 edition. The competition date is {{EventDate}}. The Bible Quizzing portion in 2020 was {{QuizBibleBooks}}.",Notes:["Only the King James Bible is used for all events."],Sections:[{Key:"general",Title:"General Rules",Items:["Only the King James Bible is used for all events.","The Bible category has seven events: Bible Preaching - Expository, Bible Preaching - Topical, Bible Storytelling, Ladies' Seminar Speaking, Bible Puppet Show, Radio Program and Bible Quizzing."]},{Key:"eligibility",Title:"Eligibility",Items:["Expository and Topical Bible Preaching are for males only.","Ladies' Seminar Speaking is for females.","Bible Storytelling is open to males and females.","Bible Puppet Show: no more than two puppeteers. The team can be all male, all female or one of each.","Bible Quizzing: team members must be in Grades 7-12.","Bible Quizzing: a team has 2 to 5 members and can include up to two substitutes from the same church.","Bible Quizzing: each church can have no more than two teams.","Radio Program: the message may come from a prerecorded sermon preached by an Independent Baptist preacher."]},{Key:"registration",Title:"How Entries Are Sent",Items:["Radio Program: send the program digitally no later than one week before the date of competition ({{RadioDeadline}}).","Radio Program: save the MP3 audio file on a CD or USB drive and mail it to the address in {{RadioMailingContact}}.","Preaching, Storytelling, Ladies' Seminar Speaking and Puppet Show: give the written copies to the judges at the time of presentation."]},{Key:"dates",Title:"Date",Items:["The competition date is {{EventDate}}."]},{Key:"other",Title:"Bible Quizzing study portion",Items:["Each year the Bible book(s) to study are announced by the body in {{StudyCycleAnnouncer}}. In 2020 the portion was {{QuizBibleBooks}}.","The King James Version is the only authorized translation for all competition purposes."]}],Documents:[{Title:"IBFAC Bible Category Rules (2020)",Url:"https://irp-cdn.multiscreensite.com/3fe07c3b/files/uploaded/2020%20Bible%20category%20rules%20IBFAC.pdf"}]},n=[],a=[{AgeGroup:"Quiz Team (Gr 7-12)",Source:"Bible Category Rules 2020, Team Membership",Sections:{About:null,TimeAndFormat:null,Rules:["Team members must be in Grades 7-12.","A team has 2 to 5 members and may include two substitutes from the same church.","Each church can have no more than two teams."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Team members must be in Grades 7-12.
- A team has 2 to 5 members and may include two substitutes from the same church.
- Each church can have no more than two teams.`}],i=JSON.parse(`[{"Title":"Bible Preaching - Expository","Source":"Bible Category Rules 2020, Bible Preaching-Expository","Sections":{"About":["An expository sermon interprets a portion of Scripture in relation to one theme. The bulk of the material is drawn directly from the passage."],"TimeAndFormat":["The presentation must be between 7 and 10 minutes long.","A time within one minute over or under the allowed time gets a 4-point deduction.","A time more than one minute over or under the allowed time gets an 8-point deduction."],"Rules":["For males only.","Each participant must give the judges three copies of his typewritten sermon in outline form at the time of presentation. Failure to do so will result in disqualification."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["A suit jacket and tie are appropriate for this competition."]},"Markdown":"## About this competition\\n- An expository sermon interprets a portion of Scripture in relation to one theme. The bulk of the material is drawn directly from the passage.\\n\\n## Time and format\\n- The presentation must be between 7 and 10 minutes long.\\n- A time within one minute over or under the allowed time gets a 4-point deduction.\\n- A time more than one minute over or under the allowed time gets an 8-point deduction.\\n\\n## Rules\\n- For males only.\\n- Each participant must give the judges three copies of his typewritten sermon in outline form at the time of presentation. Failure to do so will result in disqualification.\\n\\n## Notes for participants\\n- A suit jacket and tie are appropriate for this competition."},{"Title":"Bible Preaching - Topical","Source":"Bible Category Rules 2020, Bible Preaching-Topical","Sections":{"About":["A topical sermon uses Scripture passages to support the topic's main divisions. The Scriptures do not have to be from the same passage."],"TimeAndFormat":["The presentation must be between 7 and 10 minutes long.","A time within one minute over or under the allowed time gets a 4-point deduction.","A time more than one minute over or under the allowed time gets an 8-point deduction."],"Rules":["For males only.","Each participant must give the judges three copies of his typewritten sermon in outline form at the time of presentation. Failure to do so will result in disqualification."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["A suit jacket and tie are appropriate for this competition."]},"Markdown":"## About this competition\\n- A topical sermon uses Scripture passages to support the topic's main divisions. The Scriptures do not have to be from the same passage.\\n\\n## Time and format\\n- The presentation must be between 7 and 10 minutes long.\\n- A time within one minute over or under the allowed time gets a 4-point deduction.\\n- A time more than one minute over or under the allowed time gets an 8-point deduction.\\n\\n## Rules\\n- For males only.\\n- Each participant must give the judges three copies of his typewritten sermon in outline form at the time of presentation. Failure to do so will result in disqualification.\\n\\n## Notes for participants\\n- A suit jacket and tie are appropriate for this competition."},{"Title":"Bible Storytelling","Source":"Bible Category Rules 2020, Bible Storytelling","Sections":{"About":["Each participant prepares and tells a Bible story. The theme is a Bible character, a doctrine of the Bible or a concept from the Bible."],"TimeAndFormat":["The presentation must be between 7 and 10 minutes long.","A time within one minute over or under the allowed time gets a 4-point deduction.","A time more than one minute over or under the allowed time gets an 8-point deduction."],"Rules":["Males and females may take part.","Prepare the story as if it were for a junior-aged class, or for ages 9-12.","Each participant must give the judges three copies of his or her typewritten Bible story in outline form at the time of presentation. Failure to do so will result in disqualification."],"Allowed":["A visual aid. It does not have to be original."],"NotAllowed":null,"Judging":null,"Points":null,"Notes":["The participant's Bible should be open and visible."]},"Markdown":"## About this competition\\n- Each participant prepares and tells a Bible story. The theme is a Bible character, a doctrine of the Bible or a concept from the Bible.\\n\\n## Time and format\\n- The presentation must be between 7 and 10 minutes long.\\n- A time within one minute over or under the allowed time gets a 4-point deduction.\\n- A time more than one minute over or under the allowed time gets an 8-point deduction.\\n\\n## Rules\\n- Males and females may take part.\\n- Prepare the story as if it were for a junior-aged class, or for ages 9-12.\\n- Each participant must give the judges three copies of his or her typewritten Bible story in outline form at the time of presentation. Failure to do so will result in disqualification.\\n\\n## Allowed\\n- A visual aid. It does not have to be original.\\n\\n## Notes for participants\\n- The participant's Bible should be open and visible."},{"Title":"Ladies' Seminar Speaking","Source":"Bible Category Rules 2020, Ladies' Seminar Speaking","Sections":{"About":["Each female participant prepares a spiritually inspirational lecture for use in a seminar or conference for women. The title is \\"There's a New Song in My Heart\\"."],"TimeAndFormat":["The presentation must be between 7 and 10 minutes long.","A time within one minute over or under the allowed time gets a 4-point deduction.","A time more than one minute over or under the allowed time gets an 8-point deduction."],"Rules":["The lecture should address a topic applicable to women from a Biblical perspective.","Each participant must give the judges three copies of her typewritten lecture in outline form at the time of presentation. Failure to do so will result in disqualification."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Each female participant prepares a spiritually inspirational lecture for use in a seminar or conference for women. The title is \\"There's a New Song in My Heart\\".\\n\\n## Time and format\\n- The presentation must be between 7 and 10 minutes long.\\n- A time within one minute over or under the allowed time gets a 4-point deduction.\\n- A time more than one minute over or under the allowed time gets an 8-point deduction.\\n\\n## Rules\\n- The lecture should address a topic applicable to women from a Biblical perspective.\\n- Each participant must give the judges three copies of her typewritten lecture in outline form at the time of presentation. Failure to do so will result in disqualification."},{"Title":"Bible Puppet Show","Source":"Bible Category Rules 2020, Bible Puppet Show","Sections":{"About":["The puppet show depicts an actual Bible character and/or an actual Bible event."],"TimeAndFormat":["The presentation must be between 7 and 10 minutes long.","A time within one minute over or under the allowed time gets a 4-point deduction.","A time more than one minute over or under the allowed time gets an 8-point deduction."],"Rules":["No more than two puppeteers may be in the act. The team may be all male, all female or one of each.","A basic screen is provided to hide the puppeteers from the audience.","Three copies of the typewritten puppet show script must be given to the judges at the time of presentation. Failure to do so will result in disqualification.","The show must be tastefully presented."],"Allowed":["Homemade and professionally made puppets."],"NotAllowed":["Slang that insinuates questionable language, references to television, and worldly practices such as movies, dancing or mixed swimming."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- The puppet show depicts an actual Bible character and/or an actual Bible event.\\n\\n## Time and format\\n- The presentation must be between 7 and 10 minutes long.\\n- A time within one minute over or under the allowed time gets a 4-point deduction.\\n- A time more than one minute over or under the allowed time gets an 8-point deduction.\\n\\n## Rules\\n- No more than two puppeteers may be in the act. The team may be all male, all female or one of each.\\n- A basic screen is provided to hide the puppeteers from the audience.\\n- Three copies of the typewritten puppet show script must be given to the judges at the time of presentation. Failure to do so will result in disqualification.\\n- The show must be tastefully presented.\\n\\n## Allowed\\n- Homemade and professionally made puppets.\\n\\n## Not allowed\\n- Slang that insinuates questionable language, references to television, and worldly practices such as movies, dancing or mixed swimming."},{"Title":"Radio Program","Source":"Bible Category Rules 2020, Radio Program","Sections":{"About":["Each participant prerecords a 15-minute daily broadcast that could air on a local radio station or on internet radio."],"TimeAndFormat":["The broadcast is 15 minutes long.","The broadcast features a program opener, an introduction to the message, the message, closing comments and a program closer."],"Rules":["The participant is the announcer and voices the introductions and closings.","The message may be given by the participant, or may be a segment of a prerecorded sermon preached by an Independent Baptist preacher.","Submit the program digitally no later than one week before the date of competition. Save the MP3 file on a CD or USB drive and mail it as shown in {{RadioMailingContact}}.","Also submit a typed copy of the program script with a statement that the program is original."],"Allowed":["Background music for the program openings and closings."],"NotAllowed":["Background music with a rock beat, a sinfully sensual style or rhythm, or any inappropriate beat."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Each participant prerecords a 15-minute daily broadcast that could air on a local radio station or on internet radio.\\n\\n## Time and format\\n- The broadcast is 15 minutes long.\\n- The broadcast features a program opener, an introduction to the message, the message, closing comments and a program closer.\\n\\n## Rules\\n- The participant is the announcer and voices the introductions and closings.\\n- The message may be given by the participant, or may be a segment of a prerecorded sermon preached by an Independent Baptist preacher.\\n- Submit the program digitally no later than one week before the date of competition. Save the MP3 file on a CD or USB drive and mail it as shown in {{RadioMailingContact}}.\\n- Also submit a typed copy of the program script with a statement that the program is original.\\n\\n## Allowed\\n- Background music for the program openings and closings.\\n\\n## Not allowed\\n- Background music with a rock beat, a sinfully sensual style or rhythm, or any inappropriate beat."},{"Title":"Bible Quizzing","Source":"Bible Category Rules 2020, Bible Quizzing","Sections":{"About":["Bible Quizzing is a jump-quizzing game of Bible knowledge and speed of recall. Two or three opposing teams are asked an oral question, and the first team member to respond may answer within a time limit. Points are scored for correct answers and penalties for incorrect and incomplete answers. Individual and team scores are kept, and the highest scoring team wins. The 2020 study portion was {{QuizBibleBooks}}."],"TimeAndFormat":["A game has twenty correctly answered regular or toss-up questions, plus any free or tie-breaker questions needed.","Each question is read only once.","If no quizzer responds within ten seconds after a question is read, the question is tossed out and another is read. Tossed-out questions do not count as one of the twenty.","A quizzer has thirty seconds to answer a question. The clock starts when the Quizmaster recognizes the quizzer.","The quizzer must begin the answer within five seconds. The quizzer may begin the answer, restate the question, or say \\"My answer is...\\". Failing to begin within five seconds is an error.","Each team may call up to two time-outs per game, by the coach or the team captain. A time-out is called after one question is answered and before the next is read, and lasts no longer than one minute. No time-out is allowed after the seventeenth question has been read.","Voluntary substitutions need a time-out. Substitutions after a quizzer quizzes out or errors out do not. Other teams may substitute during one team's time-out. A time-out may also be used for a team conference."],"Rules":["Seating: the Quizmaster faces the opposing teams. Three teams sit so each can see and hear the Quizmaster and see the scoreboard. Each church's starting contestants sit as a team, numbered 1 to 5. Each team chooses a captain and a co-captain. The official mode of response is a light jump system. The Quizmaster reviews the rules and answers questions before play.","Team members may confer before any quizzer is recognized.","During or after a regular question, the first team member whose light comes on and who comes to full stature in one continuous motion is addressed by number, for example \\"CLAYS MILL ROAD BAPTIST CHURCH, NUMBER THREE.\\"","A quizzer may interrupt the reading of a regular, toss-up or tie-breaker question, but must then answer without hearing the whole question.","A correct answer to a regular question scores twenty points for the team, and another regular question is read. Each quizzer's points are tallied on a score sheet.","A quizzer who has correctly answered six twenty-point questions (quizzing out) leaves the game. An eligible substitute may replace him. He does not return to the current game. If the team captain quizzes out, the co-captain becomes the challenger.","Any incorrect or incomplete answer at the Timekeeper's call of time is an error. Each quizzer's errors are tallied on a score sheet.","A quizzer who makes six errors on regular or toss-up questions (erroring out) leaves the game. An eligible substitute may replace him. He does not return to the current game. If the team captain errors out, the co-captain becomes the challenger.","Quiz Panel: it may consist of the Quizmaster, the Scorekeeper and the Timekeeper. The Quizmaster appoints and instructs it. It decides contested decisions when the Quizmaster asks, and declares the winner. All its decisions are final.","Coaches: each team has one coach officially present during competition. A church may have any number of coaches for pre-contest preparation. The coach is responsible for the behavior of the team at all times, and the coach's behavior counts as team behavior and must meet the Dress and Conduct code. The coach may lodge a protest with the Quizmaster only after a game is completed. Courteous protests are received courteously.","Toss-up questions: after penalty points are given for a wrong answer to a regular question, the question is reread as a toss-up. Only the remaining two teams may respond. If no quizzer responds within ten seconds the question is tossed out. When only two teams compete, toss-up questions are not used, and free questions are asked to the remaining team after all incorrect answers.","Free questions: after an error on a toss-up question (or an error on a regular question when only two teams compete), the remaining team gets a new, previously unread FREE question. The first team member to rise may attempt to answer, with no penalty for an error (an \\"attempt\\"). No other attempts are allowed. An unanswered free question is tossed out.","Tie score after the twentieth question: single regular tie-breaker questions are asked until the tie is broken. Individual scores and errors continue to be tallied. If the twentieth question is answered in error, the whole round continues to the end, with the toss-up and, if needed, free question. Then single tie-breaker questions continue like a sudden-death playoff, but the quiz must end with a correctly answered regular or toss-up question.","If one team is highest and the other two are tied after the twentieth question, the winner drops out and the game continues until a tie-breaker produces second and third place.","If two teams tie for first place, the third team with the lowest score is the loser and drops out. The game continues until a tie-breaker produces a winner and a second-place team.","Fouls: talking or conferring between the time the quizzer is recognized and the time points are given or penalties are assessed; any part of the hands or feet touching the chair while a question is read; a quizzer failing to come to full stature in one continuous motion; an overly antagonistic attitude toward officials and rulings; a disagreeable attitude shown by indiscreet challenging; any behavior not conducive to the Christian spirit.","Challenges: only a team captain may challenge, by raising his hand and saying \\"Excuse me, Mr. Quizmaster, I would like to challenge.\\" He may let a team member voice it. The challenge must be made right after the points are given or penalties assessed. The Quizmaster, with or without the Quiz Panel, alone accepts or rejects it. A sustained challenge withdraws the points that would have been awarded, with no penalty to the team. An overruled challenge costs the challenging team no points.","An answer to any question (regular, toss-up, free or tie-breaker) is open to challenge if: incorrect information was thought correct; in a finish-the-verse question, the first five words are the same as those of another verse in the Scripture in competition; or correct information was thought incorrect. A challenge may also be made if a foul in the fouls rule occurred.","Questions and answers: no tossed-out question is asked again until all questions have been asked once during the whole competition. The Quizmaster alone decides if an answer is correct and may ask the Panel.","Question form, interrogative: a key word or words from Scripture plus who, whom, what, why, where, when, which or how, answered by a paraphrased word or phrase. It may be drawn from context without key words, and may or may not include the book and chapter.","Question form, finish-the-verse: begins \\"Finish this verse\\" and gives the first five words of a verse. \\"Finish these (two or three) verses\\" asks for at least two but not more than three following verses, said word for word. No reference needs to be cited.","Question form, reference: begins \\"According to...\\" with a reference (verse and chapter, or chapter alone), and may or may not use an interrogative. It is answered with a paraphrase, not word for word.","Question form, quotation: begins \\"Quote this verse\\", \\"Quote these two verses\\" or \\"Quote these three verses\\" with a book-chapter-verse reference. It is answered by the word-for-word verse. The quizzer may, but need not, cite the reference.","Correct answers: an answer is correct only if correctly and completely stated within the thirty-second limit. Quotation and finish-the-verse answers must be word for word, clearly understood and complete. For reference and interrogative questions, if the call of time interrupts extra information, the answer is correct if what came before was correct and complete. A mispronounced proper name is still correct. Only the first answer from a quizzer counts, and starting over to correct is an automatic error. When the answer is complete the quizzer sits down.","Errors: failing to begin the answer within five seconds; any incorrect or incomplete answer at the call of time; the wrong quizzer answering (the right quizzer then may answer, but if both are from the same team it is an error and the question is repeated as a toss-up); an answer that needs clarification; a word-for-word verse given for an interrogative or reference question; any change from the verse in a finish-the-verse or quotation answer (addition, omission, reversal or changed words); an incorrect answer when the quizzer interrupted the question; starting over to correct; any incorrect information in an answer."],"Allowed":null,"NotAllowed":null,"Judging":["The team with the highest score after the twentieth question or the sudden-death tie-breaker wins. The second highest is second place and the last team is third place.","Winning gives the advantage of the draw of opponents as quiz teams are eliminated. The Quizmaster decides which teams play in each game.","The competition runs as a double elimination tournament: each team must take third place twice before it is eliminated. Two second-place finishes count as one third-place finish.","One quizzer is named Star Quizzer: the quizzer with the highest average of correctly answered twenty-point questions per game, announced at the awards ceremony."],"Points":["A correct answer to a regular question scores 20 points. A correct answer to a toss-up question scores 20 points. A correct answer to a free question scores 10 points.","Beginning at the fourth team error, 10 penalty points are deducted for each error. The first three team errors do not change the score.","On the sixteenth and all later questions, 10 penalty points are deducted for each error whether or not the team had three errors before.","An incorrect answer to a toss-up question deducts 10 points from the team's score beginning at the fourth team error, and on the sixteenth and later questions in all cases.","No penalty points are given for free questions answered incorrectly, incompletely or not at all.","For every three team fouls, 10 points are deducted from the team's score."],"Notes":["Team members are in Grades 7-12. A team has 2 to 5 members and up to two substitutes from the same church. Each church can enter no more than two teams."]},"Markdown":"## About this competition\\n- Bible Quizzing is a jump-quizzing game of Bible knowledge and speed of recall. Two or three opposing teams are asked an oral question, and the first team member to respond may answer within a time limit. Points are scored for correct answers and penalties for incorrect and incomplete answers. Individual and team scores are kept, and the highest scoring team wins. The 2020 study portion was {{QuizBibleBooks}}.\\n\\n## Time and format\\n- A game has twenty correctly answered regular or toss-up questions, plus any free or tie-breaker questions needed.\\n- Each question is read only once.\\n- If no quizzer responds within ten seconds after a question is read, the question is tossed out and another is read. Tossed-out questions do not count as one of the twenty.\\n- A quizzer has thirty seconds to answer a question. The clock starts when the Quizmaster recognizes the quizzer.\\n- The quizzer must begin the answer within five seconds. The quizzer may begin the answer, restate the question, or say \\"My answer is...\\". Failing to begin within five seconds is an error.\\n- Each team may call up to two time-outs per game, by the coach or the team captain. A time-out is called after one question is answered and before the next is read, and lasts no longer than one minute. No time-out is allowed after the seventeenth question has been read.\\n- Voluntary substitutions need a time-out. Substitutions after a quizzer quizzes out or errors out do not. Other teams may substitute during one team's time-out. A time-out may also be used for a team conference.\\n\\n## Rules\\n- Seating: the Quizmaster faces the opposing teams. Three teams sit so each can see and hear the Quizmaster and see the scoreboard. Each church's starting contestants sit as a team, numbered 1 to 5. Each team chooses a captain and a co-captain. The official mode of response is a light jump system. The Quizmaster reviews the rules and answers questions before play.\\n- Team members may confer before any quizzer is recognized.\\n- During or after a regular question, the first team member whose light comes on and who comes to full stature in one continuous motion is addressed by number, for example \\"CLAYS MILL ROAD BAPTIST CHURCH, NUMBER THREE.\\"\\n- A quizzer may interrupt the reading of a regular, toss-up or tie-breaker question, but must then answer without hearing the whole question.\\n- A correct answer to a regular question scores twenty points for the team, and another regular question is read. Each quizzer's points are tallied on a score sheet.\\n- A quizzer who has correctly answered six twenty-point questions (quizzing out) leaves the game. An eligible substitute may replace him. He does not return to the current game. If the team captain quizzes out, the co-captain becomes the challenger.\\n- Any incorrect or incomplete answer at the Timekeeper's call of time is an error. Each quizzer's errors are tallied on a score sheet.\\n- A quizzer who makes six errors on regular or toss-up questions (erroring out) leaves the game. An eligible substitute may replace him. He does not return to the current game. If the team captain errors out, the co-captain becomes the challenger.\\n- Quiz Panel: it may consist of the Quizmaster, the Scorekeeper and the Timekeeper. The Quizmaster appoints and instructs it. It decides contested decisions when the Quizmaster asks, and declares the winner. All its decisions are final.\\n- Coaches: each team has one coach officially present during competition. A church may have any number of coaches for pre-contest preparation. The coach is responsible for the behavior of the team at all times, and the coach's behavior counts as team behavior and must meet the Dress and Conduct code. The coach may lodge a protest with the Quizmaster only after a game is completed. Courteous protests are received courteously.\\n- Toss-up questions: after penalty points are given for a wrong answer to a regular question, the question is reread as a toss-up. Only the remaining two teams may respond. If no quizzer responds within ten seconds the question is tossed out. When only two teams compete, toss-up questions are not used, and free questions are asked to the remaining team after all incorrect answers.\\n- Free questions: after an error on a toss-up question (or an error on a regular question when only two teams compete), the remaining team gets a new, previously unread FREE question. The first team member to rise may attempt to answer, with no penalty for an error (an \\"attempt\\"). No other attempts are allowed. An unanswered free question is tossed out.\\n- Tie score after the twentieth question: single regular tie-breaker questions are asked until the tie is broken. Individual scores and errors continue to be tallied. If the twentieth question is answered in error, the whole round continues to the end, with the toss-up and, if needed, free question. Then single tie-breaker questions continue like a sudden-death playoff, but the quiz must end with a correctly answered regular or toss-up question.\\n- If one team is highest and the other two are tied after the twentieth question, the winner drops out and the game continues until a tie-breaker produces second and third place.\\n- If two teams tie for first place, the third team with the lowest score is the loser and drops out. The game continues until a tie-breaker produces a winner and a second-place team.\\n- Fouls: talking or conferring between the time the quizzer is recognized and the time points are given or penalties are assessed; any part of the hands or feet touching the chair while a question is read; a quizzer failing to come to full stature in one continuous motion; an overly antagonistic attitude toward officials and rulings; a disagreeable attitude shown by indiscreet challenging; any behavior not conducive to the Christian spirit.\\n- Challenges: only a team captain may challenge, by raising his hand and saying \\"Excuse me, Mr. Quizmaster, I would like to challenge.\\" He may let a team member voice it. The challenge must be made right after the points are given or penalties assessed. The Quizmaster, with or without the Quiz Panel, alone accepts or rejects it. A sustained challenge withdraws the points that would have been awarded, with no penalty to the team. An overruled challenge costs the challenging team no points.\\n- An answer to any question (regular, toss-up, free or tie-breaker) is open to challenge if: incorrect information was thought correct; in a finish-the-verse question, the first five words are the same as those of another verse in the Scripture in competition; or correct information was thought incorrect. A challenge may also be made if a foul in the fouls rule occurred.\\n- Questions and answers: no tossed-out question is asked again until all questions have been asked once during the whole competition. The Quizmaster alone decides if an answer is correct and may ask the Panel.\\n- Question form, interrogative: a key word or words from Scripture plus who, whom, what, why, where, when, which or how, answered by a paraphrased word or phrase. It may be drawn from context without key words, and may or may not include the book and chapter.\\n- Question form, finish-the-verse: begins \\"Finish this verse\\" and gives the first five words of a verse. \\"Finish these (two or three) verses\\" asks for at least two but not more than three following verses, said word for word. No reference needs to be cited.\\n- Question form, reference: begins \\"According to...\\" with a reference (verse and chapter, or chapter alone), and may or may not use an interrogative. It is answered with a paraphrase, not word for word.\\n- Question form, quotation: begins \\"Quote this verse\\", \\"Quote these two verses\\" or \\"Quote these three verses\\" with a book-chapter-verse reference. It is answered by the word-for-word verse. The quizzer may, but need not, cite the reference.\\n- Correct answers: an answer is correct only if correctly and completely stated within the thirty-second limit. Quotation and finish-the-verse answers must be word for word, clearly understood and complete. For reference and interrogative questions, if the call of time interrupts extra information, the answer is correct if what came before was correct and complete. A mispronounced proper name is still correct. Only the first answer from a quizzer counts, and starting over to correct is an automatic error. When the answer is complete the quizzer sits down.\\n- Errors: failing to begin the answer within five seconds; any incorrect or incomplete answer at the call of time; the wrong quizzer answering (the right quizzer then may answer, but if both are from the same team it is an error and the question is repeated as a toss-up); an answer that needs clarification; a word-for-word verse given for an interrogative or reference question; any change from the verse in a finish-the-verse or quotation answer (addition, omission, reversal or changed words); an incorrect answer when the quizzer interrupted the question; starting over to correct; any incorrect information in an answer.\\n\\n## Judging\\n- The team with the highest score after the twentieth question or the sudden-death tie-breaker wins. The second highest is second place and the last team is third place.\\n- Winning gives the advantage of the draw of opponents as quiz teams are eliminated. The Quizmaster decides which teams play in each game.\\n- The competition runs as a double elimination tournament: each team must take third place twice before it is eliminated. Two second-place finishes count as one third-place finish.\\n- One quizzer is named Star Quizzer: the quizzer with the highest average of correctly answered twenty-point questions per game, announced at the awards ceremony.\\n\\n## Points\\n- A correct answer to a regular question scores 20 points. A correct answer to a toss-up question scores 20 points. A correct answer to a free question scores 10 points.\\n- Beginning at the fourth team error, 10 penalty points are deducted for each error. The first three team errors do not change the score.\\n- On the sixteenth and all later questions, 10 penalty points are deducted for each error whether or not the team had three errors before.\\n- An incorrect answer to a toss-up question deducts 10 points from the team's score beginning at the fourth team error, and on the sixteenth and later questions in all cases.\\n- No penalty points are given for free questions answered incorrectly, incompletely or not at all.\\n- For every three team fouls, 10 points are deducted from the team's score.\\n\\n## Notes for participants\\n- Team members are in Grades 7-12. A team has 2 to 5 members and up to two substitutes from the same church. Each church can enter no more than two teams."}]`),r=[],s=[{Key:"EventDate",Kind:"date",Label:"Competition date",Value:"To be announced",Source:"Bible Category Rules 2020 (no date printed)"},{Key:"RadioMailingContact",Kind:"contact",Label:"Radio Program entries contact",Value:{Name:"Troy Young",Role:"Radio Program entries: mail to 3000 Clays Mill Road, Lexington, Kentucky",Phone:"",WhatsApp:"",Email:""},Source:"Bible Category Rules 2020, Radio Program rule 6"},{Key:"RadioDeadline",Kind:"text",Label:"Radio Program submission deadline",Value:"No later than one week before the date of competition",Source:"Bible Category Rules 2020, Radio Program rule 6"},{Key:"QuizBibleBooks",Kind:"text",Label:"Bible Quizzing study portion",Value:"John 1-10 (2020 edition)",Source:"Bible Category Rules 2020, Bible Quizzing heading"},{Key:"StudyCycleAnnouncer",Kind:"text",Label:"Who announces the yearly Bible book(s)",Value:"Commonwealth Baptist College",Source:"Bible Category Rules 2020, Study Cycle"}],h=[{Claim:"Registration content captured from the organiser's 2020 Bible category rules.",SourceType:"Primary - the event's own rules document",Source:"Bible Category Rules 2020",Url:"https://irp-cdn.multiscreensite.com/3fe07c3b/files/uploaded/2020%20Bible%20category%20rules%20IBFAC.pdf"}],u={TemplateKey:e,Year:2020,Note:t,Page:o,ParticipantTypes:n,AgeGroups:a,Competitions:i,CompetitionAgeGroups:r,Variables:s,Evidence:h};export{a as AgeGroups,r as CompetitionAgeGroups,i as Competitions,h as Evidence,t as Note,o as Page,n as ParticipantTypes,e as TemplateKey,s as Variables,l as Year,u as default};
